"""Author the Bangladesh practice and team challenge question bank."""
from pathlib import Path
import json

ROOT=Path(__file__).resolve().parents[1]
games=[]
def game(id,title,strap,description,minutes,uses,debrief):
    g=dict(id=id,title=title,strap=strap,description=description,minutes=minutes,uses=uses,debrief=debrief,questions=[])
    games.append(g)
    return g
def q(g,section,prompt,options,answer,why,kind='single'):
    g['questions'].append(dict(id=f"{g['id']}-{len(g['questions'])+1}",section=section,kind=kind,prompt=prompt,options=options,answer=answer if isinstance(answer,list) else [answer],why=why))

g=game('rapport','Rapport Relay','Keep the issue. Lose the attack.','Rescue a tense tripartite meeting: acknowledge, reframe and ask a question that opens a way forward.',8,{'institutions':[4],'secretariats':[5]},['Which reframe would the original speaker still recognize?','Try one answer aloud, then invite a partner to improve it.'])
q(g,'Listen first','“The ministry has said ‘under consideration’ for two years. Nobody intends to act.” What is the strongest first response?',['“Please avoid making accusations.”','“You want a clear status and a decision date after a long delay.”','“The ministry is doing its best.”'],1,'Acknowledge the concern and the delay without endorsing a claim about anyone’s motives. You can then ask for a status, owner and decision date.')
q(g,'Reframe','“Employers only agreed because they know this will never be enforced.” Choose the neutral reframe.',['“Employer representatives acted in bad faith.”','“Everyone agrees enforcement is impossible.”','“Worker members seek clarity on how the agreement will be implemented and verified.”'],2,'The reframe preserves the enforceability concern. It removes the claim about motives and does not invent consensus.')
q(g,'Open the discussion','Two constituencies reject each other’s wage figures. Which question moves the discussion forward?',['“Which definition and collection period explain the difference between the series?”','“Can we agree the official number is always correct?”','“Which side is willing to withdraw its figures?”'],0,'An open question tests comparability. Record contested series and their methods; do not settle a substantive dispute by choosing a favourite source.')
q(g,'Two useful moves','A representative says, “This was decided elsewhere. We are being asked to rubber-stamp it.” Choose TWO useful moves.',['Ask which parts remain open to influence and record the answer.','Promise the representative that their proposal will be adopted.','Paraphrase the concern about meaningful participation and check you understood.','Remove the objection from the minutes to protect rapport.'],[0,2],'Check understanding and clarify the real scope for influence. Rapport does not require a promise of agreement or removal of dissent.','pair')
q(g,'Sequence the response','Put these facilitation moves in a useful order.',['Ask a specific open question about a way forward.','Acknowledge the concern.','Paraphrase the substance and check understanding.'],[1,2,0],'Listening comes first. Check that the speaker recognizes the issue before asking them to work on a possible next step.','order')
q(g,'Hold the boundary','A participant threatens non-compliance if a recommendation is adopted. What should the chair’s support team do?',['Record that there is consensus because no vote was requested.','Ask what implementation obstacles are anticipated, record the position honestly, and apply the agreed procedure.','Threaten to remove the constituency from the next meeting.'],1,'Treat the statement as information about implementation and a constituent position. Support the procedure; neither fabricate agreement nor retaliate.')

g=game('inclusion','Inclusion Detective','Find who the policy misses.','Follow the clues in a fictional wage proposal. Spot hidden barriers and repair the evidence before a decision.',10,{'institutions':[5,6],'secretariats':[8]},['Who disappears when you describe only the average worker?','Which amendment changes the actual reach of a measure?'])
q(g,'Reach test','A simulated benefit is available only to workers who upload a written contract from a registered employer. Which group is most clearly at risk of exclusion?',['Only workers who earn above the minimum wage.','Workers without written contracts, including many in informal employment.','Every member of the tripartite body.'],1,'Eligibility design can stop a measure at formal employment. Identify the actual barrier and an accessible route; do not assume everybody can produce the same documents.')
q(g,'Equal value','Two jobs have different titles but may demand comparable skill, responsibility, effort and working conditions. What should a tripartite discussion examine?',['Pay only within identical job titles.','An objective job evaluation method for comparing work of equal value.','The personal negotiating strength of each worker.'],1,'Equal remuneration for work of equal value requires an objective comparison across jobs. A comparison confined to identical titles can miss structural undervaluation.')
q(g,'Evidence clues','A wage brief quotes “2026 data”, but the survey was collected in 2022. Choose TWO repairs.',['State the collection period and the publication date separately.','Remove the series because older data are always worthless.','Explain the definition, limits and any more current comparable evidence.','Rename the series “current” because the report is new.'],[0,2],'Publication date does not make observations current. Keep the period, definition, limitations and comparability visible to all three parties.','pair')
q(g,'Wage criteria','Which brief gives the parties a useful common starting point for wage discussion?',['Only the highest proposed rate, with no sources.','Only enterprise costs because worker needs are a political question.','Evidence on worker and family needs and economic factors, with disputed series recorded and the weighting left to the parties.'],2,'The secretariat supports an agreed fact base. The parties decide the weights and the outcome; the brief must not erase either set of considerations.')
q(g,'An amendment that matters','The proposal says, “Gender should be considered.” Which replacement changes the mechanism?',['“Gender is very important.”','Require data disaggregated by sex and employment status, name who reviews gaps, and specify when a gap triggers corrective action.','Put the same sentence in a coloured box.'],1,'A real amendment changes data requirements, responsibilities or decisions. If deleting the gender paragraph changes nothing else, the design has not changed.')
q(g,'Review trigger','Which clause offers the clearest accountability?',['“The rate will be reviewed periodically.”','“Review when all parties are satisfied.”','“The secretariat will table the agreed evidence brief every 12 months; the body will consider whether revision is needed.”'],2,'A numerical interval, responsible role and tabled evidence make review predictable. This is a fictional training clause, not a statement of Bangladesh law.')

g=game('secretariat','Secretariat Sprint','Keep the room fair under pressure.','A fast succession of meeting, protocol, budget and evidence dilemmas. Protect neutrality without stopping the work.',12,{'institutions':[4,7],'secretariats':[2,3,4,6,7,8]},['Which safeguards should be routine rather than depend on personal courage?','Choose one decision to turn into a written operating procedure.'])
q(g,'Before the meeting','One constituency receives a revised paper privately the night before a meeting. What is the strongest response?',['Circulate the same version to all constituencies, record dispatch, and flag whether there is enough time for meaningful consideration.','Ask that constituency to explain it to the others at the table.','Keep the paper off the dispatch log.'],0,'Equal access means the same document and a fair chance to prepare. A dispatch log should show recipient, version, time and channel.')
q(g,'Agenda rescue','An agenda item reads “Wage paper — discussion”. Choose TWO additions that make it usable.',['The purpose and decision, if any, being sought.','A secretariat instruction that one constituency must concede.','The supporting document, version and circulation deadline.','A promise that the meeting will reach consensus.'],[0,2],'A clear purpose and advance documents make participation predictable. The secretariat cannot promise or prescribe a substantive agreement.','pair')
q(g,'Honest minutes','Two provisions were agreed; one remains contested. How should the record present the outcome?',['Use “broad consensus” for all three to protect relationships.','Record agreed provisions separately and attribute the unresolved positions fairly in the parties’ own terms.','Leave the contested provision out of the record.'],1,'An honest record distinguishes agreement from disagreement. It preserves the substance of each position and supports a real next step.')
q(g,'Chair briefing','Which sentence belongs in a neutral chair briefing?',['“The Chair should push workers to accept option B.”','“The employers’ concern is obviously the reasonable one.”','“The procedure requires advance circulation; the revised paper was sent yesterday, and members may raise the preparation time.”'],2,'Brief the chair on facts, procedure and likely issues. Do not use technical support to recommend that one party’s substantive position prevail.')
q(g,'Budget ceiling','SIMULATED: last year’s budget was 1,000 units. The maximum increase is 10%. What is the new ceiling?',['1,010 units.','1,100 units.','1,200 units.'],1,'Ten percent of 1,000 is 100. The ceiling is 1,100 fictional units. Explain priorities and trade-offs within that envelope; these are not national budget figures.')
q(g,'Audit pressure','An allowance lacks supporting documentation. The meeting is tomorrow and someone asks you to backdate a receipt. Choose the proper response.',['Backdate it so the meeting can proceed.','Refuse to fabricate evidence, record the gap and use the authorized approval or escalation process.','Delete the expenditure from the records.'],1,'A complete record includes unresolved gaps. Neither urgency nor a meeting deadline justifies inventing supporting documents.')
q(g,'Fact-base relay','Sequence the preparation of a shared wage evidence brief.',['Circulate the identical, versioned brief to all constituencies.','Check definitions, collection periods and coverage.','Record material disagreements and limits in the brief.'],[1,2,0],'Validate the evidence first, disclose material differences, then circulate a common brief. A shared fact base is not a secretariat decision on the wage outcome.','order')
q(g,'Institutional memory','A staff member rotates out next week. Which action best protects continuity?',['Keep the files in that person’s private email because they know the history.','Send only the most recent minutes and discard earlier versions.','Handover a controlled meeting file, access permissions, version history, action register and named custodian.'],2,'Institutional memory requires accessible records and responsibilities. Access should follow roles, with confidentiality and retention rules respected.')

g=game('delivery','Decision to Delivery','Turn the minutes into movement.','Repair weak commitments, choose useful indicators and rescue blocked actions before the next meeting.',10,{'institutions':[7,8,9],'secretariats':[4,9]},['Which field makes a commitment verifiable?','What should return to the agenda for decision, rather than disappear in a status report?'])
q(g,'Repair the conclusion','The minutes say, “Stakeholders will improve coordination soon.” Which version can be followed up?',['“Everyone will make their best efforts.”','“The designated secretariat officer will circulate a draft referral protocol by 30 November, with feedback due in ten working days.”','“Coordination is a priority for the future.”'],1,'Name a responsible role, an output and a date. The date and role here are fictional; adapt them to the real body’s authority and resources.')
q(g,'Two missing links','An action has an owner and deadline but no delivery evidence or resources. Choose TWO additions.',['What completed output will be checked and by whom.','A label saying “urgent” in red.','The cost or staff time and who will provide it.','An assurance that no monitoring is needed.'],[0,2],'An assigned action still needs a verification method and a resource basis. Urgency is not a substitute for feasibility.','pair')
q(g,'A useful status','Which register entry tells the body something it can act on?',['“Ongoing.”','“Progressing well.”','“Blocked: responsible unit has no approved allocation; decision on funding requested at the next meeting.”'],2,'A status should expose the obstacle, the responsible route and the required decision. A generic “ongoing” entry can hide years of inaction.')
q(g,'The tabling method','Put the follow-up cycle in order.',['Table overdue or blocked items that need a decision.','Ask each action owner for a dated status and evidence before the meeting.','Update the register and carry open actions forward with their original dates.'],[1,0,2],'Obtain a status before the meeting, table exceptions for decisions, then update the continuous register. Do not reset the original date to hide delay.','order')
q(g,'Indicator detective','Which indicator best tests whether agreed actions are being implemented on time?',['Number of chairs in the meeting room.','Share of actions due in the period completed by their agreed deadlines, with verification and a stated denominator.','Total words in the minutes.'],1,'The denominator and time period make the measure interpretable. Pair delivery indicators with meaningful inclusion or outcome measures; volume alone does not show effectiveness.')
q(g,'Reform pathway','The mandate permits referral, but papers keep getting lost between two secretariats. What is a sensible first step?',['Assume a new law is always required before changing a filing practice.','Diagnose the handover failure, agree a practical referral log and named custodians, and identify separately any change needing a formal instrument.','Create a new body before checking the existing process.'],1,'Separate failures of practice, capacity and legal authority. Start with changes within the body’s control while documenting any formal reform needed.')

g=game('action','Action Plan Rescue','Make the final presentation count.','A peer-review mission: repair an action plan so another team can tell who will do what, when and with what evidence.',8,{'institutions':[10,11,12],'secretariats':[10]},['Which improvement could your own role begin within 30 days?','What specific response will you ask the plenary for?'])
q(g,'Owner rescue','An action plan names “the ministry and social partners” as the owner. What does it need?',['A longer list of institutions.','A responsible post for the next output, a coordinating role and the other contributors’ commitments.','The name of the group that made the slide.'],1,'A named post makes follow-up possible when individuals change. Distinguish who coordinates from who decides, supplies evidence or implements.')
q(g,'A quick win','Which improvement fits an individual 30-day plan for a secretariat officer?',['Secure a major legislative amendment by yourself.','Promise a national wage increase.','Start a versioned dispatch log within your authority, with a date and a check that every constituency receives the same papers.'],2,'A quick win is something you can actually do within your role. Larger reforms may belong in the institutional roadmap with the required approvals.')
q(g,'Peer-review pair','Choose TWO questions a peer-review team should ask before endorsing an action plan.',['Is the first step within the responsible body’s mandate and resources?','Are there enough decorative graphics?','What observable evidence will show the action is complete, and by what date?','Can all unresolved disagreements be hidden?'],[0,2],'Peer review tests feasibility and verification. A clear unresolved issue is more useful than an attractive but unimplementable promise.','pair')
q(g,'Record the unknown','The group cannot establish the number of affected informal workers. What should the proposal say?',['Invent a plausible number to keep the presentation moving.','Record the unknown, the source and responsible role for obtaining it, and the decision that depends on it.','Remove informal workers from the scope without explanation.'],1,'A documented unknown with an evidence plan is a legitimate output. Do not turn a simulated assumption into a national fact.')
q(g,'Sequence a roadmap','Put the three-month improvement pathway in a sensible order.',['Build continuity: check the process is used, review gaps and handover responsibilities.','Establish a basic dispatch log and action register with responsible roles.','Use the records to produce consistent neutral briefs and follow-up reports.'],[1,2,0],'Build the foundation, use it consistently, and then check sustainability. A roadmap should name real deliverables, roles and dates.','order')
q(g,'The plenary ask','The group ends, “Thank you for listening.” What would make the presentation more useful?',['A request for a specific endorsement, commitment, factual answer or decision on ownership, with a next step recorded.','A claim that silence means every institution has committed.','A promise that every proposal will be implemented immediately.'],0,'Be explicit about what you need from the room. Record the actual response and next step, including any disagreement or missing authority.')

g=game('mandate','Whose Table Is It?','One matter. One table. Decided at the door.','Matters arrive at a national system with two national bodies, sectoral bodies and enterprise-level committees. Route each one, decide what travels with it, and settle a collision before it becomes an argument.',10,{'institutions': [2, 3], 'secretariats': [1, 2]},['In your own system, who decides where a new matter goes — and is that written down anywhere?', 'Which of these routing decisions would your institution currently argue about after the fact?'])
q(g,'Where it lands','SIMULATED: a ministry sends a draft labour instrument for views before it goes forward. Two national tripartite bodies exist. Which is the better first home?',['Whichever body meets soonest, so the ministry gets an answer quickly.', 'The body whose own instrument gives it the standing function of advising on draft labour instruments.', 'Both, so that neither constituency can say it was left out.'],[1],'Route by function, not by diary. A body with the standing function can be held to the advice it gives; a body that happened to be meeting cannot. Sending it to both invites two different answers to the same question.','single')
q(g,'Where it lands','A dispute about shift rosters in one enterprise is submitted to the national body.',['It belongs at enterprise level first; the sectoral body becomes relevant only if the same problem recurs across enterprises.', 'The national body should take it, because the worker organization asked it to.', 'It should be refused without explanation, because it is not national.'],[0],'National bodies lose authority when they absorb single-enterprise matters. Name the right level, say so in writing, and keep the door open for the pattern — several enterprises with the same problem is a sectoral question.','single')
q(g,'Where it lands','A matter arrives that no instrument assigns to anyone. What should the secretariat do?',['Hold it until somebody asks about it.', 'Return it to the sender as outside the system.', 'Record it as unallocated, propose an allocation to the chairs with reasons, and put the proposal on the next agenda.'],[2],'Gaps are findings, not embarrassments. An unallocated matter on the record with a proposed home is how a mandate gap gets closed. A matter held quietly is how one stays open for years.','single')
q(g,'What travels with it','A national body refers a matter to a sectoral body. What should travel with it?',['The adopted conclusion only, so the sectoral body starts without preconceptions.', 'The file, the positions as each constituency stated them including any dissent, the deadline and a named contact.', 'Nothing in writing; the chairs will speak.'],[1],"A conclusion without the positions behind it gets reopened at the receiving table. Dissent recorded in the parties' own terms is what lets the next body take the matter forward rather than start it again.",'single')
q(g,'What travels with it','Sequence the referral of a matter from a national body to a sectoral one.',['Transmit the file with the recorded positions, the deadline and a named contact.', 'Log the matter and record the allocation decision and its reason.', 'Confirm the receiving body has tabled it, and report that back at the next ordinary meeting.'],[1, 0, 2],'Decide and record first, transmit second, confirm third. Most referrals fail at the third step: nobody checks that the matter arrived, so it disappears between two institutions that each believe the other has it.','order')
q(g,'When two bodies claim it','Two national bodies have put the same wage question on their agendas. Choose TWO things the secretariats should do first.',['Agree which body holds the matter, and record the allocation and its reason.', 'Let both proceed and compare the conclusions afterwards.', 'Tell the organization that submitted it which body is handling it, and by when.', 'Ask the responsible minister to decide between the two bodies.'],[0, 2],"Settle it between the secretariats, in writing, and tell the submitter. Running both wastes the constituencies' time and risks two different answers; handing the choice upward turns a procedural question into a political one.",'pair')
q(g,'When two bodies claim it','The same collision keeps happening. Which fix is the most durable?',['A written rule, agreed by both bodies and published, that allocates each incoming matter at the point of entry.', 'A standing joint meeting of both bodies to resolve each collision as it arises.', 'An understanding between the two secretaries, renewed when either of them changes.'],[0],'Prevent the collision at the door rather than negotiating it afterwards. A joint meeting costs more every time; an understanding between two individuals does not survive either of them moving on.','single')
q(g,'Upward and downward','Which matter most clearly belongs with the body that holds the tripartite consultation function on international labour standards?',['A proposal to change the agenda format of a sectoral committee.', 'A question about the content of a report due to the ILO supervisory system.', 'A request for training on minute-taking for secretariat staff.'],[1],"Consultation on international labour standards is a defined function, not a general competence. Matching the matter to the function is what keeps each body's authority intact — and what tells a constituent organization where to send its submission.",'single')

out={'version':'2026-10-23','notice':'Original learning games based on the supplied revised agendas and handouts. All scenarios and numerical examples are fictional training material. They do not state Bangladesh law or assess open-ended facilitation skills.','games':games}
(ROOT/'dist'/'games'/'bank.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
(ROOT/'dist'/'game-catalog.js').write_text('window.BDGAMES = '+json.dumps([{**{k:v for k,v in g.items() if k!='questions'},'rounds':len(g['questions'])} for g in games],ensure_ascii=False,separators=(',',':'))+';\n')
print(f'{len(games)} new games, {sum(len(g["questions"]) for g in games)} rounds')
